/*
 * weida_easy.h: the blocking easy tier over libweida's Req/Rep slice.
 *
 * Hand-written, not generated by header.sh: static inline helpers over the
 * exports of weida.h, adding no export of their own. docs/c/easy.md is the
 * normative prose.
 *
 * One deadline: timeout_ms bounds the whole helper, not each step; below 0
 * waits forever and 0 only tries (R4). On any failure, -WEIDA_EAGAIN and
 * -WEIDA_EINTR included, a helper drops every op and handle it created,
 * writes no out-parameter (R2) and returns the first failing call's code;
 * the thread-local record (weida_last_error_*) is the one that call left.
 * A request may already have reached the peer when a helper gives up, so a
 * retry may send it twice. Callers that must resume across signals or
 * timeouts use weida.h directly.
 *
 * POSIX builds need clock_gettime(CLOCK_MONOTONIC): under strict ISO C
 * (-std=c11) on glibc or musl, define _POSIX_C_SOURCE 200809L before the
 * first #include, or compile with -std=gnu11.
 */
#ifndef WEIDA_EASY_H
#define WEIDA_EASY_H

#include "weida.h"

#ifdef _WIN32
#include <windows.h>
#else
#include <time.h>
#ifndef CLOCK_MONOTONIC
#error "weida_easy.h needs clock_gettime(CLOCK_MONOTONIC): define _POSIX_C_SOURCE 200809L before the first #include, or compile with -std=gnu11"
#endif
#endif

/* Internal: the monotonic clock in milliseconds, never negative. */
static inline int64_t weida_easy_now_ms_(void) {
#ifdef _WIN32
    return (int64_t)GetTickCount64();
#else
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
#endif
}

/* Internal: the absolute deadline of `timeout_ms` from now, -1 for forever
 * (a negative timeout, or one that would overflow). */
static inline int64_t weida_easy_deadline_(int64_t timeout_ms) {
    if (timeout_ms < 0)
        return -1;
    int64_t now = weida_easy_now_ms_();
    if (timeout_ms > INT64_MAX - now)
        return -1;
    return now + timeout_ms;
}

/* Internal: the milliseconds left until `deadline`, -1 for forever, 0 once
 * it passed. Computed fresh for every wait. */
static inline int64_t weida_easy_left_(int64_t deadline) {
    if (deadline < 0)
        return -1;
    int64_t left = deadline - weida_easy_now_ms_();
    return left < 0 ? 0 : left;
}

/* Client terms that trust exactly the pinned `fingerprint`. */
static inline int weida_easy_client_tls_pinned(const char *fingerprint, weida_client_tls **out) {
    if (out == NULL)
        return -WEIDA_EINVAL;
    weida_trust *trust = NULL;
    weida_client_tls *tls = NULL;
    int rc = weida_trust_new(&trust);
    if (rc < 0)
        return rc;
    rc = weida_trust_add_pin(trust, fingerprint);
    if (rc >= 0)
        rc = weida_client_tls_new(trust, &tls);
    weida_trust_drop(trust);
    if (rc < 0)
        return rc;
    *out = tls;
    return 0;
}

/* Dials `url` and waits until the connection is up. */
static inline int weida_easy_connect(const weida_requester *r, const char *url, int64_t timeout_ms) {
    int64_t deadline = weida_easy_deadline_(timeout_ms);
    weida_requester_connect_op *op = NULL;
    int rc = weida_requester_connect(r, url, &op);
    if (rc < 0)
        return rc;
    rc = weida_requester_connect_op_wait(op, weida_easy_left_(deadline));
    weida_requester_connect_op_drop(op);
    return rc < 0 ? rc : 0;
}

/* Sends `body` as one request and collects the reply, at most `max_bytes`
 * of it, into `*out`. The reply's metadata is weida_msg_meta(*out). */
static inline int weida_easy_call(const weida_requester *r,
                                  const uint8_t *body,
                                  size_t len,
                                  uint64_t max_bytes,
                                  int64_t timeout_ms,
                                  weida_msg **out) {
    if (out == NULL)
        return -WEIDA_EINVAL;
    int64_t deadline = weida_easy_deadline_(timeout_ms);
    weida_requester_request_op *exchange = NULL;
    weida_incoming_transfer *reply = NULL;
    weida_incoming_transfer_collect_op *collecting = NULL;
    weida_msg *msg = NULL;
    int rc = weida_requester_request(r, body, len, &exchange);
    if (rc < 0)
        return rc;
    rc = weida_requester_request_op_wait(exchange, weida_easy_left_(deadline), &reply);
    weida_requester_request_op_drop(exchange);
    if (rc < 0)
        return rc;
    rc = weida_incoming_transfer_collect(reply, max_bytes, &collecting);
    if (rc < 0)
        return rc;
    rc = weida_incoming_transfer_collect_op_wait(collecting, weida_easy_left_(deadline), &msg);
    weida_incoming_transfer_collect_op_drop(collecting);
    if (rc < 0)
        return rc;
    *out = msg;
    return 0;
}

/* Accepts the next request and collects its body, at most `max_bytes` of
 * it. The request still has to be answered with weida_easy_reply (or the
 * primitives) or dropped. */
static inline int weida_easy_accept(const weida_replier *rep,
                                    uint64_t max_bytes,
                                    int64_t timeout_ms,
                                    weida_incoming_request **out_request,
                                    weida_msg **out_body) {
    if (out_request == NULL || out_body == NULL)
        return -WEIDA_EINVAL;
    int64_t deadline = weida_easy_deadline_(timeout_ms);
    weida_incoming_request *q = NULL;
    weida_incoming_transfer *body = NULL;
    weida_incoming_transfer_collect_op *collecting = NULL;
    weida_msg *msg = NULL;
    int rc = weida_replier_accept(rep, weida_easy_left_(deadline), &q);
    if (rc < 0)
        return rc;
    rc = weida_incoming_request_take_body(q, &body);
    if (rc < 0) {
        weida_incoming_request_drop(q);
        return rc;
    }
    rc = weida_incoming_transfer_collect(body, max_bytes, &collecting);
    if (rc < 0) {
        weida_incoming_request_drop(q);
        return rc;
    }
    rc = weida_incoming_transfer_collect_op_wait(collecting, weida_easy_left_(deadline), &msg);
    weida_incoming_transfer_collect_op_drop(collecting);
    if (rc < 0) {
        weida_incoming_request_drop(q);
        return rc;
    }
    *out_request = q;
    *out_body = msg;
    return 0;
}

/* Answers `q` with `len` bytes of `data` and `meta` (NULL: default
 * metadata), and waits until the requester's transport has acknowledged
 * them. Consumes `q` on every return path. */
static inline int weida_easy_reply(weida_incoming_request *q,
                                   const weida_transfer_meta *meta,
                                   const uint8_t *data,
                                   size_t len,
                                   int64_t timeout_ms) {
    int64_t deadline = weida_easy_deadline_(timeout_ms);
    weida_incoming_request_reply_op *opening = NULL;
    weida_outgoing_transfer *stream = NULL;
    weida_delivery *delivery = NULL;
    weida_delivery_delivered_op *delivered = NULL;
    int rc = weida_incoming_request_reply(q, meta, &opening);
    if (rc < 0)
        return rc;
    rc = weida_incoming_request_reply_op_wait(opening, weida_easy_left_(deadline), &stream);
    weida_incoming_request_reply_op_drop(opening);
    if (rc < 0)
        return rc;
    while (len > 0) {
        size_t n = 0;
        rc = weida_outgoing_transfer_write(stream, data, len, weida_easy_left_(deadline), &n);
        if (rc < 0) {
            weida_outgoing_transfer_drop(stream);
            return rc;
        }
        data += n;
        len -= n;
    }
    rc = weida_outgoing_transfer_finish(stream, &delivery);
    if (rc < 0)
        return rc;
    rc = weida_delivery_delivered(delivery, &delivered);
    if (rc < 0)
        return rc;
    rc = weida_delivery_delivered_op_wait(delivered, weida_easy_left_(deadline));
    weida_delivery_delivered_op_drop(delivered);
    return rc < 0 ? rc : 0;
}

/* Shuts the runtime down and waits until it stopped. Consumes `rt`. */
static inline int weida_easy_shutdown(weida_runtime *rt, int64_t timeout_ms) {
    int64_t deadline = weida_easy_deadline_(timeout_ms);
    weida_runtime_shutdown_op *op = NULL;
    int rc = weida_runtime_shutdown(rt, &op);
    if (rc < 0)
        return rc;
    rc = weida_runtime_shutdown_op_wait(op, weida_easy_left_(deadline));
    weida_runtime_shutdown_op_drop(op);
    return rc < 0 ? rc : 0;
}

#endif /* WEIDA_EASY_H */
